#!/usr/bin/env python3
"""Minimal PEP 503 "simple" PyPI index server.

Serves the distribution files found in DIST_DIR under /simple/ so that
    pip install --index-url http://localhost:8080/simple <project>==<version>
works against this server.
"""
import hashlib
import os
import re
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

DIST_DIR = os.environ.get("SIMPLE_DIST_DIR", "/app/vectorops/dist")
HOST = os.environ.get("SIMPLE_HOST", "0.0.0.0")
PORT = int(os.environ.get("SIMPLE_PORT", "8080"))


def normalize(name):
    """PEP 503 project-name normalization."""
    return re.sub(r"[-_.]+", "-", name).lower()


def project_name_of(fname):
    """Extract the project name from a dist filename (<name>-<version>...)."""
    m = re.match(r"^(.*?)[-_](?=\d)", fname)
    return normalize(m.group(1)) if m else None


def sha256_of(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 16), b""):
            h.update(chunk)
    return h.hexdigest()


def dist_files():
    """Return {normalized project name: [(filename, sha256hex), ...]} for DIST_DIR."""
    projects = {}
    for fname in sorted(os.listdir(DIST_DIR)):
        path = os.path.join(DIST_DIR, fname)
        if not os.path.isfile(path):
            continue
        if not (fname.endswith(".whl") or fname.endswith(".tar.gz")):
            continue
        project = project_name_of(fname)
        if project is None:
            continue
        projects.setdefault(project, []).append((fname, sha256_of(path)))
    return projects


class Handler(BaseHTTPRequestHandler):
    server_version = "MiniPyPI/1.0"
    protocol_version = "HTTP/1.1"

    def _send_bytes(self, code, body, content_type):
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-cache, no-store, must-revalidate")
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _send_html(self, code, html):
        self._send_bytes(code, html.encode("utf-8"), "text/html; charset=utf-8")

    def _not_found(self):
        self._send_html(404, "<html><body><h1>404 Not Found</h1></body></html>")

    def _handle(self):
        parts = [p for p in urlsplit(self.path).path.split("/") if p]
        if not parts:
            return self._send_html(
                200,
                "<html><body><h1>Local PyPI simple index</h1>"
                "<p><a href=\"/simple/\">/simple/</a></p></body></html>",
            )
        if parts[0] != "simple":
            return self._not_found()
        if len(parts) == 1:
            html = ["<!DOCTYPE html><html><body><ul>"]
            for project in sorted(dist_files()):
                html.append('<a href="{}/">{}</a>'.format(project, project))
            html.append("</ul></body></html>")
            return self._send_html(200, "".join(html))
        project = normalize(unquote(parts[1]))
        files = dist_files().get(project)
        if not files:
            return self._not_found()
        if len(parts) == 2:
            html = ["<!DOCTYPE html><html><body><ul>"]
            for fname, digest in files:
                html.append(
                    '<a href="{}#sha256={}" data-requires-python=">=3.8">{}</a>'.format(
                        fname, digest, fname
                    )
                )
            html.append("</ul></body></html>")
            return self._send_html(200, "".join(html))
        fname = unquote(parts[2])
        path = os.path.realpath(os.path.join(DIST_DIR, os.path.basename(fname)))
        if not path.startswith(os.path.realpath(DIST_DIR) + os.sep):
            return self._not_found()
        if fname not in {f for f, _ in files} or not os.path.isfile(path):
            return self._
